import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const sourceFiles = [
    'js/languages.js',
    'js/reading.js',
    'js/core.js',
    'js/app.js',
];

const toClassicScript = (source) => source
    .replace(/^import\s+[\s\S]*?\s+from\s+['"][^'"]+['"];\s*/gm, '')
    .replace(/\bexport\s+const\b/g, 'const')
    .replace(/^export\s+\{[^}]+\};\s*$/gm, '');

const sections = sourceFiles.map((relativePath) => {
    const source = fs.readFileSync(path.join(root, relativePath), 'utf8');
    return `\n/* Source: ${relativePath} */\n${toClassicScript(source).trim()}\n`;
});

const bundle = `/* TinyCode Web browser bundle. Generated by tools/build-bundle.mjs. */
(() => {
'use strict';
${sections.join('\n')}
})();
`;

fs.writeFileSync(path.join(root, 'js/app.bundle.js'), bundle, 'utf8');
console.log(`Built js/app.bundle.js (${Buffer.byteLength(bundle).toLocaleString('en-US')} bytes).`);
